 users:{title:'کاربران',single:'کاربر',desc:'حساب‌های دعوت‌شده و وضعیت دسترسی',icon:'♙',cols:[['name','نام'],['username','نام کاربری'],['email','ایمیل'],['phone','تلفن'],['status','وضعیت'],['last_login_at','آخرین ورود']],filters:[['status','وضعیت',[['active','فعال'],['suspended','تعلیق'],['invited','دعوت‌شده']]]],fields:[['name','نام','text',1],['username','نام کاربری'],['email','ایمیل','email'],['phone','تلفن'],['status','وضعیت',[['active','فعال'],['suspended','تعلیق'],['invited','دعوت‌شده']]],['temporary_password','رمز موقت','password']]},
