const relRoutes={products:'products',companies:'companies',contacts:'contacts',opportunities:'opportunities',tasks:'tasks',quotations:'quotations',routes:'routes',documents:'documents',countries:'countries',categories:'categories',industries:'industries'};
async function api(path,opt={}){const headers={'Accept':'application/json',...(opt.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(S.csrf?{'X-CSRF-Token':S.csrf}:{}),...(opt.headers||{})};let res=await fetch('/api/'+path,{...opt,headers});let json=await res.json().catch(()=>({ok:false,message:'پاسخ نامعتبر سرور'}));if(res.status===401){showLogin();throw Error(json.message||'نشست پایان یافته است.')}if(!res.ok||!json.ok){const err=Error(json.message||'خطا در عملیات');err.status=res.status;err.errors=json.errors||{};throw err}return json}
function can(code){return S.permissions.includes('*')||S.permissions.includes(code)}
function route(){let p=location.pathname.replace(/^\/+|\/+$/g,'').split('/').filter(Boolean);return{resource:p[0]||'dashboard',id:p[1]&&/^\d+$/.test(p[1])?+p[1]:null,action:p.slice(2).join('/'),query:new URLSearchParams(location.search)}}
function go(url,replace=false){history[replace?'replaceState':'pushState']({},'',url);renderRoute()}
function status(v){let c=['verified','approved','issued','active','won','done','accepted'].includes(v)?'good':['urgent','overdue','rejected','lost','cancelled','expired'].includes(v)?'danger':['under_review','review','in_progress','on_hold','open','received'].includes(v)?'wait':'unknown';return`<span class="status ${c}">${E(labels[v]||v||'نامشخص')}</span>`}
function optionName(type,id){const a=S.meta[type]||[];return a.find(x=>String(x.id)===String(id))?.name||id||'—'}
function format(k,v){if(v===null||v==='')return'—';const map={category_id:'categories',parent_id:k==='parent_id'?'categories':null,default_unit_id:'units',unit_id:'units',currency_id:'currencies',country_id:'countries',origin_country_id:'countries',destination_country_id:'countries',reporter_country_id:'countries',partner_country_id:'countries',stage_id:'stages',owner_user_id:'users',assigned_to:'users',user_id:'users',product_id:'products',company_id:'companies',linked_company_id:'companies',opportunity_id:'opportunities',route_id:'routes',transport_method_id:'transport_methods',insurance_product_id:'insurance_products',source_id:'trade_sources'};if(map[k])return E(optionName(map[k],v));if(k==='status'||k.endsWith('_status')||['priority','opportunity_type','flow','document_type','quotation_direction','price_type','provider_type','is_active'].includes(k))return status(String(v));if(k.endsWith('_at')||k.endsWith('_date')||['valid_until','expires_at','start_date','target_close_date','valid_from'].includes(k))return new Date(v).toLocaleDateString('fa-IR');if(typeof v==='object')return E(JSON.stringify(v));return E(v)}
function crumb(items){return`<div class="breadcrumbs"><a href="/dashboard" data-link>TradeDesk</a>${items.map((x,i)=>`<span> / </span>${x[1]?`<a href="${x[1]}" data-link>${E(x[0])}</a>`:E(x[0])}`).join('')}</div>`}
function head(title,desc,actions='',crumbs=[]){return`<div class="page-head"><div>${crumb(crumbs)}<h1>${E(title)}</h1><p>${E(desc)}</p></div><div class="head-actions">${actions}</div></div>`}
function panel(title,body,sub=''){return`<section class="panel"><div class="panel-head"><div><h3>${E(title)}</h3>${sub?`<small>${E(sub)}</small>`:''}</div></div><div class="panel-body">${body}</div></section>`}
function empty(title='هنوز داده‌ای ثبت نشده',text='برای شروع از عملیات مجاز همین صفحه استفاده کنید.'){return`<div class="empty"><b>${E(title)}</b>${E(text)}</div>`}
function table(headers,rows){return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${E(x)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty()}
function loading(){document.title='در حال بارگذاری | TradeDesk';$('#content').innerHTML='<section class="page"><div class="loading-state">در حال دریافت داده از سرور…</div></section>'}
function showError(e){if(e.status===403)return unauthorized();$('#content').innerHTML=`<section class="page"><div class="error-state"><b>نمایش صفحه ممکن نشد</b><p>${E(e.message)}</p><button class="btn" data-retry>تلاش دوباره</button></div></section>`}
function unauthorized(){$('#content').innerHTML=`<section class="page unauthorized"><h1>دسترسی غیرمجاز</h1><p>نقش فعلی شما مجوز مشاهده یا انجام این عملیات را ندارد.</p><a class="btn primary" href="/dashboard" data-link>بازگشت به داشبورد</a></section>`}
function toast(msg,bad=false){const t=$('#toast');t.textContent=msg;t.className='toast show'+(bad?' error':'');clearTimeout(toast.t);toast.t=setTimeout(()=>t.className='toast',3200)}
function showLogin(){$('#login').classList.remove('hidden');$('#app').classList.add('hidden')}
function boot(auth){Object.assign(S,auth.data);$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#sideName').textContent=$('#headerName').textContent=S.user.name;$('#sideRoles').textContent=(S.roles||[]).map(x=>x.name).join('، ')||'کاربر سامانه';renderNav();loadMeta().then(renderRoute).catch(showError)}
const permissionModule=r=>({'hs-codes':'regulatory',regulations:'regulatory',categories:'references',industries:'references',countries:'references',currencies:'references',units:'references','transport-quotes':'transport','insurance-products':'insurance','insurance-quotes':'insurance','trade-statistics':'trade_statistics','trade-imports':'trade_statistics','company-leads':'trade_leads','audit-logs':'audit'}[r]||r);
function renderNav(){$('#nav').innerHTML=menu.map(([g,items])=>`<div class="nav-group">${g}</div>${items.filter(([r])=>r==='settings'||can(permissionModule(r)+'.view')||(r==='trade-imports'&&can('trade_statistics.import'))).map(([r,t,i])=>`<a href="/${r}" data-link data-nav="${r}"><span class="nav-icon">${i}</span>${t}</a>`).join('')}`).join('')}
async function loadMeta(){const r=await api('meta');S.meta=r.data;S.meta.opportunities=[];const o=await api('opportunities?limit=100&sort=title&dir=asc');S.meta.opportunities=o.data.map(x=>({id:x.id,name:`${x.reference_number} · ${x.title}`}));S.meta.routes=(await api('routes?limit=100&sort=name&dir=asc')).data.map(x=>({id:x.id,name:x.name}));S.meta.insurance_products=(await api('insurance-products?limit=100&sort=name&dir=asc')).data.map(x=>({id:x.id,name:x.name}));S.meta.trade_sources=S.meta.trade_sources||[]}
async function dashboard(){if(!can('dashboard.view'))return unauthorized();let r=await api('dashboard'),d=r.data,c=d.counts;$('#content').innerHTML=`<section class="page">${head('کارهای روز','نمای زنده از رکوردهای دیتابیس و اقدام‌های نیازمند توجه',`<a class="btn primary" href="/opportunities/new" data-link>＋ ایجاد فرصت</a>`)}<div class="cards">${[['فرصت باز',c.open_opportunities,'/opportunities'],['وظیفه عقب‌افتاده',c.overdue_tasks,'/tasks?status=open'],['کالا',c.products,'/products'],['شرکت',c.companies,'/companies'],['سند نزدیک انقضا',c.expiring_documents,'/documents']].map(x=>`<a class="card metric" href="${x[2]}" data-link><span>${x[0]}</span><strong>${Number(x[1]).toLocaleString('fa')}</strong></a>`).join('')}</div><div class="grid-2">${panel('صف اقدام من',d.tasks.length?d.tasks.map(t=>`<a class="task-row" href="/tasks/${t.id}" data-link><b>${E(t.title)}</b><span>${E(t.reference_number||'بدون پرونده')} · ${E(t.assignee)} · ${format('due_at',t.due_at)}</span></a>`).join(''):empty())}${panel('پرونده‌های منتظر یا متوقف',d.waiting.length?d.waiting.map(o=>`<a class="task-row" href="/opportunities/${o.id}" data-link><b>${E(o.reference_number)} · ${E(o.title)}</b><span>${status(o.status)} · ${status(o.priority)}</span></a>`).join(''):empty())}</div></section>`}
function queryState(name,q){const key='td-list-'+name;if(q.toString())sessionStorage.setItem(key,q.toString());else{const saved=sessionStorage.getItem(key);if(saved)q=new URLSearchParams(saved)}return q}
async function listPage(name){const c=R[name];if(!c)return notFound();let q=queryState(name,new URLSearchParams(location.search));if(!q.has('page'))q.set('page','1');if(!q.has('limit'))q.set('limit','25');loading();let r=await api(name+'?'+q),rows=r.data,m=r.meta;let filters=(c.filters||[]).map(f=>field(f,q.get(f[0])||'',true)).join('');$('#content').innerHTML=`<section class="page">${head(c.title,c.desc,can(permissionModule(name)+'.create')&&c.fields!==null?`<button class="btn primary" data-new="${name}">＋ ایجاد ${c.single}</button>`:'',[[c.title]])}<div class="toolbar"><input class="search-field" data-filter-q placeholder="جست‌وجو در ${c.title}…" value="${E(q.get('q')||'')}">${filters}<select data-filter-name="sort"><option value="id">مرتب‌سازی: جدیدترین</option>${c.cols.map(x=>`<option value="${x[0]}" ${q.get('sort')===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div id="listWrap">${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${c.cols.map(x=>`<th>${x[1]}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr data-open="/${name}/${row.id}">${c.cols.map((x,i)=>`<td>${i===0?`<a href="/${name}/${row.id}" data-link>${format(x[0],row[x[0]])}</a>`:format(x[0],row[x[0]])}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="pagination"><span>${Number(m.total).toLocaleString('fa')} رکورد · صفحه ${m.page} از ${Math.max(1,m.pages)}</span><div><button class="btn small" data-page="${m.page-1}" ${m.page<=1?'disabled':''}>قبلی</button><button class="btn small" data-page="${m.page+1}" ${m.page>=m.pages?'disabled':''}>بعدی</button></div></div></div>`:empty('رکوردی پیدا نشد','فیلترها را تغییر دهید یا رکورد جدید بسازید.')}</div></section>`}
function field(f,v='',filter=false){let[n,l,t='text',req]=f;let choices=Array.isArray(t)?t:(options[t]||S.meta[t]);if(choices){return`<label class="${filter?'filter-field':''}">${filter?'':E(l)}<select name="${E(n)}" ${filter?`data-filter-name="${E(n)}"`:''} ${req?'required':''}><option value="">${filter?'همه '+l:'انتخاب کنید'}</option>${choices.map(x=>{const val=Array.isArray(x)?x[0]:x.id,txt=Array.isArray(x)?x[1]:x.name;return`<option value="${E(val)}" ${String(v)===String(val)?'selected':''}>${E(txt)}</option>`}).join('')}</select></label>`}if(t==='textarea')return`<label class="full">${E(l)}<textarea name="${E(n)}" ${req?'required':''}>${E(v)}</textarea></label>`;return`<label>${E(l)}<input name="${E(n)}" type="${E(t)}" value="${E(v)}" ${req?'required':''} step="any"></label>`}
async function detailPage(name,id){const c=R[name];loading();const r=(await api(`${name}/${id}`)).data,rec=r.record,rel=r.related||{};document.title=`${recordTitle(name,rec)} | TradeDesk`;const pm=permissionModule(name),actions=`${can(pm+'.edit')&&c.fields.length?`<button class="btn" data-edit="${name}" data-id="${id}">ویرایش</button>`:''}${can(pm+'.archive')?`<button class="btn danger" data-archive="${name}" data-id="${id}">آرشیو</button>`:''}<a class="btn" href="/${name}${sessionStorage.getItem('td-list-'+name)?'?'+sessionStorage.getItem('td-list-'+name):''}" data-link>بازگشت به فهرست</a>`;let summary=c.cols.slice(0,6).map(x=>`<div class="summary-item"><small>${x[1]}</small><b>${format(x[0],rec[x[0]])}</b></div>`).join('');$('#content').innerHTML=`<section class="page">${crumb([[c.title,'/'+name],[recordTitle(name,rec)]])}<div class="detail-hero"><div class="detail-head"><div class="detail-title"><small>${E(c.single)} · #${id}</small><h1>${E(recordTitle(name,rec))}</h1><p>آخرین تغییر: ${format('updated_at',rec.updated_at||rec.created_at)}</p></div><div class="head-actions">${actions}</div></div><div class="detail-meta">${summary}</div>${detailTabs(name,rel)}</div><div class="detail-grid"><div class="stack" id="detailMain">${detailSections(name,rec,rel)}</div><aside class="stack">${panel('وضعیت داده',`<div class="summary-grid"><div class="summary-item"><small>منبع</small><b>${E(rec.source_name||rec.source_description||'ثبت کاربر سامانه')}</b></div><div class="summary-item"><small>اعتبارسنجی</small><b>${status(rec.verification_status||rec.classification_status||rec.status)}</b></div><div class="summary-item"><small>تاریخ بررسی</small><b>${format('checked_at',rec.checked_at)}</b></div><div class="summary-item"><small>بازبین</small><b>${format('verified_by',rec.verified_by)}</b></div></div>`)}${auditPanel(name,id)}</aside></div></section>`}
function recordTitle(name,r){return r.title||r.name_fa||r.legal_name||[r.first_name,r.last_name].filter(Boolean).join(' ')||r.name||r.reference_number||r.code||R[name]?.single}
function detailTabs(name,rel){const names={products:['هویت','مشخصات','HS Code','کشورها','اسناد فنی','آنالیز','قیمت','شرکت‌ها','فرصت‌ها'],opportunities:['خلاصه','اقلام','طرف‌ها','پیشنهادها','حمل','بیمه','اسناد','وظایف و فعالیت‌ها','تصمیم‌ها','تاریخچه'],companies:['هویت','نقش‌ها','اشخاص','کالاها','صنایع','فرصت‌ها','تعاملات'],documents:['مشخصات','نسخه‌ها','تأییدها','preview'],routes:['خلاصه','legها','استعلام‌ها']};return names[name]?`<div class="tabs">${names[name].map((x,i)=>`<button class="${i?'':'active'}">${x}</button>`).join('')}</div>`:''}
function detailSections(name,r,rel){if(name==='opportunities')return opportunitySections(r,rel);if(name==='products')return productSections(r,rel);if(name==='documents')return documentSections(r,rel);if(name==='quotations')return quotationSections(r,rel);if(name==='routes')return routeSections(r,rel);let blocks=[panel('اطلاعات رکورد',`<div class="summary-grid">${Object.entries(r).filter(([k])=>!['id','created_at','updated_at','password'].includes(k)).map(([k,v])=>`<div class="summary-item"><small>${E(fieldLabel(name,k))}</small><b>${format(k,v)}</b></div>`).join('')}</div>`)];for(const[k,rows]of Object.entries(rel))blocks.push(panel(relationTitle(k),relatedTable(k,rows)));return blocks.join('')}
function fieldLabel(name,k){return R[name]?.cols.find(x=>x[0]===k)?.[1]||R[name]?.fields.find(x=>x[0]===k)?.[1]||k.replaceAll('_',' ')}
function relationTitle(k){return({aliases:'نام‌های جایگزین',attributes:'مشخصات فنی',hs_codes:'HS Codeها',origins:'کشورها و مبادی',documents:'اسناد',analysis:'آنالیزها',companies:'شرکت‌ها',prices:'سوابق قیمت',opportunities:'فرصت‌ها',roles:'نقش‌ها',contacts:'اشخاص تماس',industries:'صنایع',activities:'فعالیت‌ها',tasks:'وظایف',items:'اقلام',parties:'طرف‌ها',decisions:'تصمیم‌ها',quotations:'پیشنهادها',transport_quotes:'استعلام‌های حمل',insurance_quotes:'استعلام‌های بیمه',history:'تاریخچه مرحله',legs:'مراحل مسیر',quotes:'استعلام‌ها',versions:'نسخه‌ها',approvals:'تأییدها',children:'زیرمجموعه‌ها',trade_coverage:'پوشش آماری',batches:'ورودهای داده'}[k]||k)}
function relationHref(k,r){const map={hs_codes:'hs-codes',companies:'companies',contacts:'contacts',opportunities:'opportunities',tasks:'tasks',quotations:'quotations',prices:'prices',transport_quotes:'transport-quotes',insurance_quotes:'insurance-quotes',documents:'documents',children:null,quotes:'transport-quotes'};const resource=map[k];if(!resource)return null;const id=r.id||r[resource.replaceAll('-','_').replace(/s$/,'')+'_id']||r.company_id||r.contact_id||r.opportunity_id;return id?`/${resource}/${id}`:null}
function relatedTable(k,rows){if(!rows?.length)return empty();const keys=Object.keys(rows[0]).filter(x=>!['old_values_json','new_values_json','content_snapshot_json','password'].includes(x)).slice(0,7);return table(keys.map(x=>fieldLabel('',x)),rows.map(r=>{const href=relationHref(k,r);return`<tr${href?` data-open="${href}"`:''}>${keys.map((x,i)=>`<td>${i===0&&href?`<a href="${href}" data-link>${format(x,r[x])}</a>`:format(x,r[x])}</td>`).join('')}</tr>`}))}
function productSections(r,rel){return[panel('هویت و شرح',`<div class="summary-grid">${[['کد',r.internal_code],['نام فارسی',r.name_fa],['نام انگلیسی',r.name_en],['نام تجاری',r.trade_name],['دسته',optionName('categories',r.category_id)],['واحد',optionName('units',r.default_unit_id)]].map(x=>`<div class="summary-item"><small>${x[0]}</small><b>${E(x[1]||'—')}</b></div>`).join('')}</div><p>${E(r.full_description||r.short_description||'توضیحی ثبت نشده است.')}</p>`),panel('مشخصات فنی ساخت‌یافته',relatedTable('attributes',rel.attributes||[])),panel('HS Code',relatedTable('hs_codes',rel.hs_codes||[]),'هیچ کد بدون منبع تأییدشده تلقی نمی‌شود.'),panel('کشورها و مبادی',relatedTable('origins',rel.origins||[])),panel('اسناد فنی و آنالیز',relatedTable('documents',rel.documents||[])+relatedTable('analysis',rel.analysis||[])),panel('قیمت، شرکت و فرصت مرتبط',relatedTable('prices',rel.prices||[])+relatedTable('companies',rel.companies||[])+relatedTable('opportunities',rel.opportunities||[]))].join('')}
function opportunitySections(r,rel){return[panel('خلاصه و عملیات',`<div class="summary-grid"><div class="summary-item"><small>مرحله</small><b>${optionName('stages',r.stage_id)}</b></div><div class="summary-item"><small>مسئول</small><b>${optionName('users',r.owner_user_id)}</b></div><div class="summary-item"><small>اولویت</small><b>${status(r.priority)}</b></div><div class="summary-item"><small>ارزش برآوردی</small><b>${E(r.estimated_amount||'—')} ${E(optionName('currencies',r.currency_id))}</b></div></div><div class="head-actions"><button class="btn" data-workflow="stage" data-id="${r.id}">تغییر مرحله</button><button class="btn" data-workflow="activity" data-id="${r.id}">ثبت فعالیت</button><button class="btn" data-workflow="decision" data-id="${r.id}">ثبت تصمیم</button></div>`),panel('اقلام درخواست',relatedTable('items',rel.items||[]),'مشخصات معامله از پرونده مرجع کالا جداست.'),panel('طرف‌ها و نقش پرونده‌ای',relatedTable('parties',rel.parties||[])),panel('پیشنهادها',relatedTable('quotations',rel.quotations||[])),panel('حمل و بیمه',relatedTable('transport_quotes',rel.transport_quotes||[])+relatedTable('insurance_quotes',rel.insurance_quotes||[])),panel('اسناد',relatedTable('documents',rel.documents||[])),panel('وظایف و فعالیت‌ها',relatedTable('tasks',rel.tasks||[])+relatedTable('activities',rel.activities||[])),panel('تصمیم‌ها و تاریخچه',relatedTable('decisions',rel.decisions||[])+relatedTable('history',rel.history||[]))].join('')}
function quotationSections(r,rel){return panel('شرایط پیشنهاد',`<div class="summary-grid">${[['فرصت',optionName('opportunities',r.opportunity_id)],['شرکت',optionName('companies',r.company_id)],['جهت',labels[r.quotation_direction]],['ارز',optionName('currencies',r.currency_id)],['پرداخت',r.payment_terms],['تحویل',r.delivery_terms],['تاریخ',r.quotation_date],['اعتبار',r.valid_until]].map(x=>`<div class="summary-item"><small>${x[0]}</small><b>${E(x[1]||'—')}</b></div>`).join('')}</div>`)+panel('اقلام پیشنهاد',relatedTable('items',rel.items||[]))+`<div class="comparison-warning">مقایسه قطعی تنها برای ارز، واحد، مقدار و شروط همسان انجام می‌شود.</div>`}
function routeSections(r,rel){return panel('مبدأ و مقصد',`<div class="summary-grid"><div class="summary-item"><small>مبدأ</small><b>${E(optionName('countries',r.origin_country_id))}</b></div><div class="summary-item"><small>مقصد</small><b>${E(optionName('countries',r.destination_country_id))}</b></div><div class="summary-item"><small>وضعیت</small><b>${status(r.status)}</b></div></div>`)+panel('مراحل مرتب مسیر',relatedTable('legs',rel.legs||[]))+panel('استعلام‌های مرتبط',relatedTable('quotes',rel.quotes||[]))}
function documentSections(r,rel){let current=(rel.versions||[])[0];return panel('مشخصات و workflow',`<div class="summary-grid">${[['نوع',labels[r.document_type]||r.document_type],['فرصت',optionName('opportunities',r.opportunity_id)],['طرف',optionName('companies',r.company_id)],['نسخه جاری',r.current_version],['وضعیت',labels[r.status]],['انقضا',r.expires_at]].map(x=>`<div class="summary-item"><small>${x[0]}</small><b>${E(x[1]||'—')}</b></div>`).join('')}</div><div class="head-actions"><button class="btn" data-workflow="version" data-id="${r.id}">نسخه جدید</button>${current?`<button class="btn" data-workflow="approve" data-id="${r.id}" data-version="${current.id}">بازبینی/تأیید</button>`:''}<button class="btn primary" data-workflow="issue" data-id="${r.id}">صدور</button></div>`)+panel('نسخه‌های immutable',relatedTable('versions',rel.versions||[]))+panel('تأییدها',relatedTable('approvals',rel.approvals||[]))+panel('Preview چاپی',current?`<article class="document-preview"><small>نسخه ${current.version_number} · snapshot ثبت‌شده</small><pre>${E(JSON.stringify(JSON.parse(current.content_snapshot_json||'{}'),null,2))}</pre><button class="btn" onclick="print()">چاپ / ذخیره PDF مرورگر</button></article>`:empty('نسخه‌ای وجود ندارد'))}
function auditPanel(name,id){return panel('ممیزی و تاریخچه',`<p>تغییرات حساس این رکورد در Audit Log ثبت می‌شوند.</p><a class="btn small" href="/audit-logs?q=${encodeURIComponent(name)}" data-link>مشاهده لاگ مرتبط</a>`)}
async function openForm(name,id=null){const c=R[name];if(!c?.fields?.length)return toast('برای این موجودیت فرم مستقیم تعریف نشده است.',true);let rec={};if(id)rec=(await api(`${name}/${id}`)).data.record;openDrawer(`${id?'ویرایش':'ایجاد'} ${c.single}`,`<form id="resourceForm" class="form-grid">${c.fields.map(f=>field(f,rec[f[0]]??'')).join('')}<div class="form-actions"><button type="button" class="btn" data-close-drawer>انصراف</button><button class="btn primary">ذخیره</button></div></form>`);$('#resourceForm').onsubmit=async e=>{e.preventDefault();const body=formData(e.target);if(id&&rec.updated_at)body.updated_at=rec.updated_at;try{let x=await api(name+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(body)});closeDrawer();toast('اطلاعات ذخیره شد.');go(`/${name}/${id||x.data.id}`)}catch(err){formError(e.target,err)}}}
function formData(form){const d=Object.fromEntries(new FormData(form));for(const k in d)if(d[k]==='')d[k]=null;return d}
function formError(form,e){toast(e.message,true);for(const[k,msg]of Object.entries(e.errors||{})){const el=form.elements[k];if(el){el.setAttribute('aria-invalid','true');el.title=msg}}}
function openDrawer(title,html){$('#drawerTitle').textContent=title;$('#drawerBody').innerHTML=html;$('#drawer').classList.add('open');$('#drawerBackdrop').classList.add('open');$('#drawer').setAttribute('aria-hidden','false')}
function closeDrawer(){$('#drawer').classList.remove('open');$('#drawerBackdrop').classList.remove('open');$('#drawer').setAttribute('aria-hidden','true')}
function optionField(name,label,type,required=true){return field([name,label,type,required?'1':null])}
function opportunityWizard(){let step=1,data={items:[{}],parties:[{}]};window.__wizardData=data;window.__wizardStep=()=>step;const draw=()=>{let content=step===1?`${field(['title','عنوان','text',1],data.title)}${field(['opportunity_type','نوع','opportunity_type',1],data.opportunity_type)}${field(['stage_id','مرحله','stages',1],data.stage_id)}${field(['owner_user_id','مسئول','users'],data.owner_user_id)}${field(['priority','اولویت','priority'],data.priority)}${field(['confidentiality_level','محرمانگی',[['team','تیم'],['restricted','محدود']]],data.confidentiality_level)}${field(['target_close_date','موعد','date'],data.target_close_date)}${field(['description','منبع درخواست و شرح','textarea'],data.description)}`:step===2?`<div class="full line-items">${data.items.map((x,i)=>`<div class="line-item" data-item="${i}">${field(['product_id','کالا','products',1],x.product_id)}${field(['quantity','مقدار','number',1],x.quantity)}${field(['unit_id','واحد','units',1],x.unit_id)}${field(['origin_country_id','مبدأ','countries'],x.origin_country_id)}${field(['destination_country_id','مقصد','countries'],x.destination_country_id)}${field(['packaging','بسته‌بندی'],x.packaging)}${field(['requested_specifications','مشخصات درخواستی','textarea'],x.requested_specifications)}<button type="button" class="btn danger" data-remove-item="${i}">حذف قلم</button></div>`).join('')}</div><button type="button" class="btn full" data-add-item>＋ افزودن قلم کالا</button>`:step===3?`<div class="full line-items">${data.parties.map((x,i)=>`<div class="line-item" data-party="${i}">${field(['company_id','شرکت','companies',1],x.company_id)}${field(['contact_id','شخص تماس','contacts'],x.contact_id)}${field(['party_role','نقش',[['buyer','خریدار'],['seller','فروشنده'],['manufacturer','تولیدکننده'],['intermediary','واسطه'],['agent','نماینده'],['other','سایر']],1],x.party_role)}${field(['relationship_status','وضعیت رابطه'],x.relationship_status)}<button type="button" class="btn danger" data-remove-party="${i}">حذف طرف</button></div>`).join('')}</div><button type="button" class="btn full" data-add-party>＋ افزودن طرف</button>`:`<div class="full notice"><b>مرور فرصت</b><p>${E(data.title)} · ${data.items.length} قلم · ${data.parties.length} طرف</p><p>پس از ذخیره، رکورد واقعی در دیتابیس ساخته می‌شود و تاریخچه مرحله ثبت خواهد شد.</p></div>`;openDrawer(`فرصت جدید · گام ${step} از ۴`,`<form id="opportunityWizard" class="form-grid">${content}<div class="form-actions">${step>1?'<button type="button" class="btn" data-wizard-back>قبلی</button>':'<button type="button" class="btn" data-close-drawer>انصراف</button>'}<button class="btn primary">${step===4?'ذخیره و ورود به پرونده':'ادامه'}</button></div></form>`);bindWizard(draw,()=>{step--},async()=>{if(step<4){captureWizard();step++;draw()}else{let x=await api('opportunities',{method:'POST',body:JSON.stringify(data)});closeDrawer();toast('فرصت و روابط آن ثبت شد.');go('/opportunities/'+x.data.id)}})};draw()}
function captureWizard(){const f=$("#opportunityWizard"),data=window.__wizardData;if(!f||!data)return;const flat=formData(f);if($("[data-item]"))dataFromRows("item",data.items);else if($("[data-party]"))dataFromRows("party",data.parties);else Object.assign(data,flat)}
function dataFromRows(kind,target){$$(`[data-${kind}]`).forEach((row,i)=>target[i]=formData(row.closest('.line-item')||row))}
function bindWizard(draw,back,submit){const f=$("#opportunityWizard"),data=window.__wizardData;f.onsubmit=async e=>{e.preventDefault();try{captureWizard();await submit()}catch(err){formError(f,err)}};$("[data-wizard-back]")?.addEventListener("click",()=>{back();draw()});$("[data-add-item]")?.addEventListener("click",()=>{dataFromRows("item",data.items);data.items.push({});draw()});$("[data-add-party]")?.addEventListener("click",()=>{dataFromRows("party",data.parties);data.parties.push({});draw()});$$("[data-remove-item]").forEach(b=>b.onclick=()=>{data.items.splice(+b.dataset.removeItem,1);if(!data.items.length)data.items.push({});draw()});$$("[data-remove-party]").forEach(b=>b.onclick=()=>{data.parties.splice(+b.dataset.removeParty,1);if(!data.parties.length)data.parties.push({});draw()})}
async function workflow(type,id,version){if(type==='stage')return simpleWorkflow('تغییر مرحله',`${field(['stage_id','مرحله جدید','stages',1])}${field(['reason','دلیل','textarea',1])}`,`opportunities/${id}/stage`,'مرحله تغییر کرد.');if(type==='activity')return simpleWorkflow('ثبت فعالیت',`${field(['activity_type','نوع',[['call','تماس'],['meeting','جلسه'],['email_note','ایمیل'],['internal_note','یادداشت']],1])}${field(['subject','موضوع','text',1])}${field(['body','شرح','textarea'])}${field(['occurred_at','زمان','datetime-local'])}`,`opportunities/${id}/activities`,'فعالیت ثبت شد.');if(type==='decision')return simpleWorkflow('ثبت تصمیم',`${field(['subject','موضوع تصمیم','text',1])}${field(['decision','نتیجه',[['selected','انتخاب'],['rejected','رد'],['deferred','تعویق'],['needs_information','نیازمند اطلاعات']],1])}${field(['selected_option','گزینه منتخب'])}${field(['reason','دلیل','textarea',1])}`,`opportunities/${id}/decisions`,'تصمیم ثبت شد.');if(type==='version')return simpleWorkflow('نسخه جدید سند',`${field(['change_summary','خلاصه تغییر','textarea',1])}${field(['snapshot','Snapshot JSON','textarea',1],'{"title":"نسخه جدید"}')}`,`documents/${id}/versions`,'نسخه immutable ساخته شد.',d=>({...d,snapshot:JSON.parse(d.snapshot)}));if(type==='approve')return simpleWorkflow('بازبینی سند',`${field(['decision','تصمیم',[['approved','تأیید'],['rejected','رد'],['changes_requested','نیازمند تغییر']],1])}${field(['reason','دلیل','textarea'])}`,`documents/${id}/approve`,'تصمیم بازبینی ثبت شد.',d=>({...d,document_version_id:+version}));if(type==='issue'){if(!confirm('سند پس از صدور immutable است. ادامه می‌دهید؟'))return;await api(`documents/${id}/issue`,{method:'POST',body:'{}'});toast('سند صادر شد.');return renderRoute()}}
function simpleWorkflow(title,fields,url,msg,transform=x=>x){openDrawer(title,`<form id="workflowForm" class="form-grid">${fields}<div class="form-actions"><button type="button" class="btn" data-close-drawer>انصراف</button><button class="btn primary">ثبت</button></div></form>`);$('#workflowForm').onsubmit=async e=>{e.preventDefault();try{await api(url,{method:'POST',body:JSON.stringify(transform(formData(e.target)))});closeDrawer();toast(msg);renderRoute()}catch(err){formError(e.target,err)}}}
async function tradeImport(){if(!can('trade_statistics.import'))return unauthorized();$('#content').innerHTML=`<section class="page">${head('ورود آمار تجارت','CSV/XLSX با mapping، اعتبارسنجی و import batch؛ بدون scraping', '',[['ورود داده']])}<div class="notice">در نبود API key، مسیر مستقل CSV فعال است. XLSX امن ذخیره می‌شود اما برای پردازش نیازمند reader/provider مجاز است.</div>${panel('بارگذاری و پیش‌نمایش',`<form id="importForm" class="form-grid" enctype="multipart/form-data">${field(['source_id','منبع داده','trade_sources',1])}<label>فایل CSV/XLSX<input name="file" type="file" accept=".csv,.xlsx" required></label><label class="full">Mapping JSON<textarea name="mapping_json" required>{"period_year":"year","hs_code":"hs_code","reporter_country_id":"reporter_country_id","partner_country_id":"partner_country_id","flow":"flow","trade_value":"trade_value","currency_id":"currency_id","net_weight":"net_weight","quantity":"quantity","unit_id":"unit_id","source_record_id":"source_record_id"}</textarea></label><div class="form-actions"><button class="btn primary">بارگذاری امن</button></div></form><div id="importResult"></div>`)}</section>`;$('#importForm').onsubmit=async e=>{e.preventDefault();try{let r=await api('trade-imports/upload',{method:'POST',body:new FormData(e.target)});$('#importResult').innerHTML=`<div class="notice"><b>Batch #${r.data.id} ثبت شد.</b><p>ستون‌ها: ${E((r.data.columns||[]).join('، '))}</p><button class="btn primary" data-import-commit="${r.data.id}">اعتبارسنجی و ثبت CSV</button></div>`}catch(err){toast(err.message,true)}}}
async function reports(){let d=(await api('reports/summary')).data;$('#content').innerHTML=`<section class="page">${head('گزارش‌ها','محاسبه مستقیم از DB؛ گروه‌های ارز و واحد جدا هستند.',can('reports.export')?'<a class="btn primary" href="/api/reports/export">خروجی CSV</a>':'', [['گزارش‌ها']])}<div class="report-grid">${panel('Pipeline فرصت‌ها',relatedTable('opportunities',d.opportunities))}${panel('قیمت به تفکیک ارز/واحد',relatedTable('prices',d.prices))}${panel('هزینه حمل به تفکیک ارز',relatedTable('transport',d.transport))}${panel('بیمه به تفکیک ارز',relatedTable('insurance',d.insurance))}</div><div class="notice">زمان محاسبه: ${E(d.generated_at)}. هیچ ارز متفاوتی با هم جمع نشده است.</div></section>`}
async function settings(){let me=(await api('auth/me')).data;$('#content').innerHTML=`<section class="page">${head('پروفایل و تنظیمات','حساب، نقش‌ها و مسیر داده‌های پایه', '',[['تنظیمات']])}<div class="grid-2">${panel('پروفایل کاربر',`<div class="summary-grid"><div class="summary-item"><small>نام</small><b>${E(me.user.name)}</b></div><div class="summary-item"><small>ایمیل</small><b>${E(me.user.email)}</b></div><div class="summary-item"><small>تلفن</small><b>${E(me.user.phone)}</b></div><div class="summary-item"><small>نقش‌ها</small><b>${E(me.roles.map(x=>x.name).join('، '))}</b></div></div><button class="btn" data-password>تغییر رمز</button>`)}${panel('داده‌های پایه',menu[1][1].slice(1).map(x=>`<a class="task-row" href="/${x[0]}" data-link><b>${x[1]}</b><span>فهرست و مدیریت مرجع</span></a>`).join(''))}</div></section>`}
function notFound(){$('#content').innerHTML=`<section class="page unauthorized"><h1>صفحه پیدا نشد</h1><p>مسیر درخواست‌شده وجود ندارد یا منتقل شده است.</p><a class="btn primary" href="/dashboard" data-link>داشبورد</a></section>`}
async function renderRoute(){if(!S.user)return;closeDrawer();const r=route();$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===r.resource));loading();try{if(r.resource==='dashboard')await dashboard();else if(r.resource==='reports')await reports();else if(r.resource==='settings'||r.resource==='profile')await settings();else if(r.resource==='trade-imports')await tradeImport();else if(r.resource==='opportunities'&&r.action==='new'||(r.resource==='opportunities'&&!r.id&&location.pathname.endsWith('/new')))opportunityWizard();else if(R[r.resource]&&r.id)await detailPage(r.resource,r.id);else if(R[r.resource])await listPage(r.resource);else notFound()}catch(e){showError(e)}}
document.addEventListener('click',async e=>{const link=e.target.closest('[data-link]');if(link){e.preventDefault();go(link.getAttribute('href'));return}const row=e.target.closest('[data-open]');if(row&&!e.target.closest('a,button'))return go(row.dataset.open);const b=e.target.closest('button');if(!b)return;if(b.dataset.new){if(b.dataset.new==='opportunities')opportunityWizard();else openForm(b.dataset.new)}if(b.dataset.edit)openForm(b.dataset.edit,+b.dataset.id);if(b.dataset.page){let q=new URLSearchParams(location.search);q.set('page',b.dataset.page);go(location.pathname+'?'+q)}if(b.dataset.archive){if(confirm('رکورد آرشیو شود؟ سابقه حذف نخواهد شد.')){try{await api(`${b.dataset.archive}/${b.dataset.id}/archive`,{method:'POST',body:'{}'});toast('رکورد آرشیو شد.');go('/'+b.dataset.archive)}catch(err){toast(err.message,true)}}}if(b.dataset.workflow)workflow(b.dataset.workflow,+b.dataset.id,b.dataset.version);if(b.dataset.closeDrawer!==undefined)closeDrawer();if(b.dataset.action==='logout'){await api('auth/logout',{method:'POST',body:'{}'});location.href='/'}if(b.dataset.retry!==undefined)renderRoute();if(b.dataset.password!==undefined)simpleWorkflow('تغییر رمز',`${field(['current_password','رمز فعلی','password',1])}${field(['new_password','رمز جدید','password',1])}`,'auth/password','رمز تغییر کرد.');if(b.dataset.importCommit){try{let mapping=JSON.parse($('#importForm [name=mapping_json]').value);let r=await api(`trade-imports/${b.dataset.importCommit}/commit`,{method:'POST',body:JSON.stringify({mapping})});toast(`${r.data.valid} ردیف ثبت و ${r.data.invalid} ردیف رد شد.`);go('/trade-statistics')}catch(err){toast(err.message,true)}}});
let filterTimer;document.addEventListener('input',e=>{if(e.target.matches('[data-filter-q]')){clearTimeout(filterTimer);filterTimer=setTimeout(()=>{let q=new URLSearchParams(location.search);q.set('q',e.target.value);q.set('page','1');go(location.pathname+'?'+q,true)},400)}});document.addEventListener('change',e=>{if(e.target.dataset.filterName){let q=new URLSearchParams(location.search);e.target.value?q.set(e.target.dataset.filterName,e.target.value):q.delete(e.target.dataset.filterName);q.set('page','1');go(location.pathname+'?'+q,true)}});document.addEventListener('click',e=>{if(e.target.closest('[data-close-drawer]'))closeDrawer();if(!e.target.closest('.global-search'))$('#searchResults').classList.add('hidden')});
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{boot(await api('auth/login',{method:'POST',body:JSON.stringify(formData(e.target))}))}catch(err){$('#loginError').textContent=err.message}};$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#drawerBackdrop').onclick=closeDrawer;$('#globalSearch').oninput=e=>{clearTimeout(filterTimer);filterTimer=setTimeout(async()=>{const q=e.target.value.trim(),box=$('#searchResults');if(q.length<2)return box.classList.add('hidden');try{let r=await api('search?q='+encodeURIComponent(q));box.innerHTML=r.data.map(x=>`<a href="/${x.type==='product'?'products':x.type==='company'?'companies':x.type==='contact'?'contacts':'opportunities'}/${x.id}" data-link><b>${E(x.title)}</b><small>${E(x.type)} · ${E(x.code)}</small></a>`).join('')||empty('نتیجه‌ای پیدا نشد');box.classList.remove('hidden')}catch{}},300)};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus()}});window.addEventListener('popstate',renderRoute);api('auth/me').then(boot).catch(showLogin);
